import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_movie import Search_movie
from Get_movie_keywords import Get_movie_keywords

import traceback

# Module-level constants derived from user requirement
SEARCH_QUERY = "The Hunger Games"


def search_movie_id(query: str) -> int:
    """Search for a movie and return the ID of the first result."""
    data = Search_movie(query)
    # Rule 10: access exact schema keys
    results = data.get("results", [])
    if not results:
        raise ValueError(f"No movies found for query: {query!r}")
    return results[0]["id"]


def fetch_keywords(movie_id: int) -> list:
    """Fetch keywords for a movie and return a list of keyword names."""
    data = Get_movie_keywords(movie_id)
    # Schema: keywords is an array of objects with 'name'
    keywords = data.get("keywords", [])
    if not keywords:
        return []  # empty list is a valid success state (Rule 7)
    return [kw["name"] for kw in keywords]


def main():
    try:
        movie_id = search_movie_id(SEARCH_QUERY)
        print(f"Movie ID for '{SEARCH_QUERY}': {movie_id}")
        keyword_list = fetch_keywords(movie_id)
        print(f"Keywords for '{SEARCH_QUERY}':")
        if not keyword_list:
            print("  (none)")
        else:
            for kw in keyword_list:
                print(f"  - {kw}")
    except Exception:
        # Rule 9: print full traceback to stderr
        traceback.print_exc(file=sys.stderr)


if __name__ == "__main__":
    main()

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_person import Search_person
from Get_person_tv_credits import Get_person_tv_credits
from Get_tv_details import Get_tv_details

import traceback

# ─── Module‑level constants ───────────────────────────────────────────
PERSON_NAME = "David Schwimmer"


# ─── Helper functions ─────────────────────────────────────────────────

def search_person(name):
    """Search for a person by name and return their TMDB ID,
    or None if no results are found."""
    data = Search_person(query=name)
    results = data.get("results", [])
    if not results:
        return None
    # Assume first result is the correct person
    person = results[0]
    return person.get("id")


def get_tv_credits(person_id):
    """Retrieve the TV cast credits for a given person.
    Returns the list of cast entries (empty list if none)."""
    credits = Get_person_tv_credits(person_id=person_id)
    return credits.get("cast", [])


def find_most_popular_show(cast_list):
    """From a list of TV cast credits, return the show ID with
    the highest 'popularity' value, or None if the list is empty."""
    most_popular = None
    max_popularity = -1.0
    for show in cast_list:
        popularity = show.get("popularity", 0)
        if popularity > max_popularity:
            max_popularity = popularity
            most_popular = show
    if most_popular is None:
        return None
    return most_popular.get("id")


def get_tv_details(show_id):
    """Return the name of a TV show given its TMDB series ID,
    or None if the name cannot be retrieved."""
    details = Get_tv_details(series_id=show_id)
    return details.get("name")


# ─── Main orchestration ───────────────────────────────────────────────

def main():
    person_id = search_person(PERSON_NAME)
    if person_id is None:
        print(f"Person '{PERSON_NAME}' not found.")
        return

    cast = get_tv_credits(person_id)
    if not cast:
        print(f"No TV credits found for {PERSON_NAME}.")
        return

    top_show_id = find_most_popular_show(cast)
    if top_show_id is None:
        print("No TV shows with a popularity score found.")
        return

    show_name = get_tv_details(top_show_id)
    if show_name is None:
        print("Could not retrieve details of the most popular TV show.")
    else:
        print(f"The most popular TV show of {PERSON_NAME} is: {show_name}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_movie import Search_movie
from Get_movie_details import Get_movie_details
from Get_company_details import Get_company_details

import traceback

# Module-level constants derived from user requirement
MOVIE_TITLE = "The Shawshank Redemption"


def find_movie_id(title):
    """
    Searches for a movie by title and returns the TMDB id of the first result.
    """
    search_result = Search_movie(title)
    results = search_result.get("results", [])
    if not results:
        return None
    return results[0].get("id")


def get_first_production_company_id(movie_id):
    """
    Fetches movie details and returns the id of the first production company.
    """
    details = Get_movie_details(movie_id)
    companies = details.get("production_companies", [])
    if not companies:
        return None
    return companies[0].get("id")


def get_company_headquarters(company_id):
    """
    Fetches company details and returns its headquarters location.
    """
    company = Get_company_details(company_id)
    return company.get("headquarters")


def main():
    try:
        movie_id = find_movie_id(MOVIE_TITLE)
        if movie_id is None:
            print(f"Movie '{MOVIE_TITLE}' not found.")
            return

        company_id = get_first_production_company_id(movie_id)
        if company_id is None:
            print("No production company found for this movie.")
            return

        hq = get_company_headquarters(company_id)
        if hq is None:
            print("Headquarters information is not available.")
        else:
            print(
                f"The headquarters of the company that created "
                f"'{MOVIE_TITLE}' is: {hq}"
            )
    except Exception:
        traceback.print_exc(file=sys.stderr)


if __name__ == "__main__":
    main()
